<?php

namespace Appstore\Bundle\RestaurantBundle\Repository;
use Appstore\Bundle\InventoryBundle\Entity\InventoryConfig;
use Appstore\Bundle\RestaurantBundle\Entity\Coupon;
use Doctrine\ORM\EntityRepository;
use Setting\Bundle\ToolBundle\Entity\GlobalOption;

/**
 * CouponRepository
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 */
class CouponRepository extends EntityRepository
{

    public function getValidCouponCode(GlobalOption $globalOption , $data)
    {

        $config = $globalOption->getRestaurantConfig()->getId();
        $datetime = new \DateTime("now");
        $today_startdatetime = $datetime->format('Y-m-d 00:00:00');
        $today_enddatetime = $datetime->format('Y-m-d 23:59:59');
        $code = (isset($data['coupon_code']) and $data['coupon_code']) ? $data['coupon_code']:'';
        $amount = (isset($data['amount']) and $data['amount']) ? $data['amount']:'';

        $qb = $this->createQueryBuilder('coupon');
        $qb->where("coupon.status = 1");
        $qb->andWhere("coupon.restaurantConfig =".$config );
        $qb->andWhere("coupon.couponCode = :couponCode");
        $qb->setParameter('couponCode', $code);
        $qb->andWhere('coupon.startDate <= :startDate');
        $qb->setParameter('startDate', $today_startdatetime);
        $qb->andWhere('coupon.endDate >= :endDate');
        $qb->setParameter('endDate', $today_enddatetime);
        $qb->andWhere('coupon.amount <= :amount');
        $qb->setParameter('amount', $amount);
        $row = $qb->getQuery()->getOneOrNullResult();
        $data = array();
        if($row){
            $data['id'] = (int) $row->getId();
            $data['name'] = $row->getName();
            $data['coupon_code'] = $row->getCouponCode();
            $data['amount'] = $row->getAmount();
            $data['limit_amount'] = $row->getAmountLimit();
            $data['valid_amount'] = $row->getValidAmount();
            $data['start_date'] = $row->getStartDate()->format('Y-m-d');
            $data['end_date'] = $row->getEndDate()->format('Y-m-d');
            $data['percentage'] = $row->getPercentage();
            $data['quantity'] = $row->getQuantity();
            $data['remaining_quantity'] = $row->getRemainingQuantity();
            $data['status'] = $row->getStatus();
        }
        return $data;


    }

    public function getApiDiscountCoupon(GlobalOption $entity)
    {
        $config = $entity->getRestaurantConfig()->getId();
        $result = $this->createQueryBuilder('e')
            ->andWhere("e.restaurantConfig ={$config}")
            ->orderBy("e.name","ASC")
            ->getQuery()->getResult();

        /* @var $row Coupon */

        $data = array();

        foreach($result as $key => $row ){

            $data[$key]['id'] = (int) $row->getId();
            $data[$key]['name'] = $row->getName();
            $data[$key]['coupon_code'] = $row->getCouponCode();
            $data[$key]['amount'] = $row->getAmount();
            $data[$key]['limit_amount'] = $row->getAmountLimit();
            $data[$key]['valid_amount'] = $row->getValidAmount();
            $data[$key]['start_date'] = $row->getStartDate()->format('Y-m-d');
            $data[$key]['end_date'] = $row->getEndDate()->format('Y-m-d');
            $data[$key]['percentage'] = $row->getPercentage();
            $data[$key]['quantity'] = $row->getQuantity();
            $data[$key]['remaining_quantity'] = $row->getRemainingQuantity();
            $data[$key]['status'] = $row->getStatus();
        }
        return $data;

    }


}
